#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long MOD = 1000000007;
    string s;
    cin >> s;
    long long dp[26], nxt[26];  // dp[c]: valid prefixes ending with letter c
    for (int c = 0; c < 26; c++) dp[c] = (s[0] == '?' || s[0] - 'a' == c) ? 1 : 0;
    for (size_t i = 1; i < s.size(); i++) {
        long long total = 0;
        for (int c = 0; c < 26; c++) total += dp[c];
        total %= MOD;
        for (int c = 0; c < 26; c++)
            nxt[c] = (s[i] == '?' || s[i] - 'a' == c) ? (total - dp[c] + MOD) % MOD : 0;
        memcpy(dp, nxt, sizeof dp);
    }
    long long answer = 0;
    for (int c = 0; c < 26; c++) answer += dp[c];
    printf("%lld\n", answer % MOD);
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1_000_000_007L;
        String s = next();
        long[] dp = new long[26], next = new long[26]; // dp[c]: valid prefixes ending with letter c
        for (int c = 0; c < 26; c++) dp[c] = s.charAt(0) == '?' || s.charAt(0) - 'a' == c ? 1 : 0;
        for (int i = 1; i < s.length(); i++) {
            char ch = s.charAt(i);
            long total = 0;
            for (int c = 0; c < 26; c++) total += dp[c];
            total %= MOD;
            for (int c = 0; c < 26; c++) next[c] = ch == '?' || ch - 'a' == c ? (total - dp[c] + MOD) % MOD : 0;
            long[] t = dp; dp = next; next = t;
        }
        long answer = 0;
        for (int c = 0; c < 26; c++) answer += dp[c];
        System.out.println(answer % MOD);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	const MOD = 1000000007
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	s := nextToken()
	var dp, next [26]int64 // dp[c]: valid prefixes ending with letter c
	for c := 0; c < 26; c++ {
		if s[0] == '?' || int(s[0]-'a') == c {
			dp[c] = 1
		}
	}
	for i := 1; i < len(s); i++ {
		var total int64
		for c := 0; c < 26; c++ {
			total += dp[c]
		}
		total %= MOD
		for c := 0; c < 26; c++ {
			next[c] = 0
			if s[i] == '?' || int(s[i]-'a') == c {
				next[c] = (total - dp[c] + MOD) % MOD
			}
		}
		dp = next
	}
	var answer int64
	for c := 0; c < 26; c++ {
		answer += dp[c]
	}
	fmt.Println(answer % MOD)
}
